from __future__ import annotations

import sys

try:
    if sys.flags.int_max_str_digits:
        sys.set_int_max_str_digits(0)
except Exception:
    pass


_WS = " \t\n\r"


class _ReturnSignal(Exception):
    def __init__(self, value: object, pos: int):
        self.value = value
        self.pos = pos


class _TopReturn(Exception):
    def __init__(self, value: object, pos: int):
        self.value = value
        self.pos = pos


def _fail(pos: int) -> None:
    raise ValueError(f"invalid JSON at position {pos}")


def _is_hex_digit(ch: str) -> bool:
    return ch.isdigit() or ("A" <= ch <= "F") or ("a" <= ch <= "f")


def _parse_hex4(s: str, i: int, base: int) -> int:
    if i + 4 > len(s):
        _fail(i)
    v = 0
    for j in range(4):
        c = s[i + j]
        if not _is_hex_digit(c):
            _fail(i + j)
        if "0" <= c <= "9":
            v = v * 16 + (ord(c) - 48)
        elif "A" <= c <= "F":
            v = v * 16 + (ord(c) - 55)
        else:
            v = v * 16 + (ord(c) - 87)
    return v


def _decode_string(s: str, i: int, expect_close: bool = True) -> tuple[str, int]:
    # s[i] must be '"' unless this is an implicit continuation check; caller ensures it.
    # This is used for object keys and scalar strings.
    n = len(s)
    if i >= n or s[i] != '"':
        _fail(i)
    i += 1
    pieces: list[str] = []
    while i < n:
        ch = s[i]
        if ch == '"':
            if not expect_close:
                _fail(i)
            return "".join(pieces), i + 1
        if ch == "\\":
            if i + 1 >= n:
                _fail(i)
            esc = s[i + 1]
            if esc == '"':
                pieces.append('"')
                i += 2
            elif esc == "\\":
                pieces.append("\\")
                i += 2
            elif esc == "/":
                pieces.append("/")
                i += 2
            elif esc == "b":
                pieces.append("\b")
                i += 2
            elif esc == "f":
                pieces.append("\f")
                i += 2
            elif esc == "n":
                pieces.append("\n")
                i += 2
            elif esc == "r":
                pieces.append("\r")
                i += 2
            elif esc == "t":
                pieces.append("\t")
                i += 2
            elif esc == "u":
                if i + 2 >= n or not (
                    s[i + 2] == "D"
                    and s[i + 3] in "89ABab"
                    or s[i + 2] == "D"
                    and s[i + 3] in "ABab"
                    or s[i + 2] == "d"
                    and s[i + 3] in "89ab"
                ):
                    pass
                cp = _parse_hex4(s, i + 2, 16)
                if 0xD800 <= cp <= 0xDBFF:
                    if i + 10 > n or s[i + 6] != "\\" or s[i + 7] != "u":
                        _fail(i)
                    low = _parse_hex4(s, i + 8, 16)
                    if not (0xDC00 <= low <= 0xDFFF):
                        _fail(i + 8)
                    combined = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00)
                    pieces.append(chr(combined))
                    i += 10
                elif 0xDC00 <= cp <= 0xDFFF:
                    _fail(i)
                else:
                    pieces.append(chr(cp))
                    i += 6
            else:
                _fail(i)
        elif 0x00 <= ord(ch) <= 0x1F:
            # Unescaped control characters (except DEL is allowed by this problem statement? The text says U+0000-U+001F are invalid; U+007F and later are allowed.)
            # So DEL (U+007F) is allowed. This branch catches only 0x00-0x1F.
            _fail(i)
        else:
            # If a non-escaped surrogate is seen directly, accept it as-is to satisfy the rule that U+007F and later may be written directly.
            pieces.append(ch)
            i += 1
    _fail(i)


def _parse_integer(s: str, i: int) -> tuple[bool, int]:
    if i >= len(s):
        _fail(i)
    neg = False
    if s[i] == "-":
        if i + 1 >= len(s) or not s[i + 1].isdigit():
            _fail(i)
        neg = True
        i += 1
    if i >= len(s) or not s[i].isdigit():
        _fail(i)
    if s[i] == "0":
        if i + 1 < len(s) and s[i + 1].isdigit():
            _fail(i + 1)
    else:
        while i < len(s) and s[i].isdigit():
            i += 1
    sign = -1 if neg else 1
    # Use built-in int for exactness; it is C code and fast enough for <= 1,000,000 characters.
    return sign, int(s[1:] if sign == -1 else s[:i]) if s[:i] not in ("",) else int(s[:i])


def _parse_number(s: str, i: int) -> object:
    if i >= len(s):
        _fail(i)
    sign = 1
    if s[i] == "-":
        if i + 1 >= len(s) or not s[i + 1].isdigit():
            _fail(i)
        sign = -1
        i += 1
    if i >= len(s) or not s[i].isdigit():
        _fail(i)
    if s[i] == "0":
        if i + 1 < len(s) and s[i + 1].isdigit():
            _fail(i + 1)
    else:
        while i < len(s) and s[i].isdigit():
            i += 1
    # If exponent or fraction follows, float() can be expensive / overflow. The problem
    # only tests values of length up to 1,000,000; for large positive exponents that
    # are obviously beyond IEEE-754 range, return inf early.
    if i < len(s) and s[i] in "eE":
        epos = i
        i += 1
        if i >= len(s):
            _fail(epos)
        exsign = 1
        if s[i] == "+":
            i += 1
        elif s[i] == "-":
            exsign = -1
            i += 1
        if i >= len(s) or not s[i].isdigit():
            _fail(epos)
        while i < len(s) and s[i].isdigit():
            i += 1
        # For values with a decimal point and/or exponent, return the same as float()
        # would. For ordinary finite cases this is exact. For extremely small values
        # underflow to 0; for large overflow return inf/-inf.
        try:
            val = float(s[:i])
        except OverflowError:
            val = float("-inf") if sign < 0 else float("inf")
        return val
    # No fraction/exponent: exact integer value.
    return int(s[:i]) * sign


def _skip_ws(s: str, i: int) -> int:
    n = len(s)
    while i < n and s[i] in _WS:
        i += 1
    return i


def parse_json(text: str) -> object:
    if not isinstance(text, str):
        raise ValueError("invalid JSON")

    n = len(text)

    # If the input is empty or only whitespace, invalid.
    if n == 0:
        _fail(0)

    # Skip leading whitespace at top level only.
    i = _skip_ws(text, 0)

    if i >= n:
        _fail(0)

    # Top-level value.
    if text[i] == "{":
        return _parse_object_top(text, i)
    if text[i] == "[":
        return _parse_array_top(text, i)

    # Otherwise, it must be a scalar JSON value.
    if text[i] in "tn":
        if text.startswith("true", i):
            i += 4
        elif text.startswith("false", i):
            i += 5
        elif text.startswith("null", i):
            i += 4
        else:
            _fail(i)
        i = _skip_ws(text, i)
        if i != n:
            _fail(i)
        return (True if text[i - 4:i].startswith("true") else None if text[i - 4:i] == "null" else False)

    if text[i] == "-" or text[i].isdigit():
        val = _parse_number(text, i)
        if isinstance(val, _ReturnSignal):
            i = val.pos
            j = _skip_ws(text, i)
            if j != n:
                _fail(j)
            return val.value
        if isinstance(val, _TopReturn):
            i = val.pos
            j = _skip_ws(text, i)
            if j != n:
                _fail(j)
            return val.value
        # _parse_number returns the final value (no position) for scalars? Actually _parse_number returns value directly above; adjust signature.
        return val

    # Leading character invalid.
    _fail(i)


# Top-level helpers: they return the top-level value and ensure trailing whitespace only.
def _parse_object_top(s: str, i: int) -> dict:
    n = len(s)
    if i >= n or s[i] != "{":
        _fail(i)
    i += 1
    i = _skip_ws(s, i)
    if i >= n:
        _fail(i)
    if s[i] == "}":
        return {}
    if s[i] != '"':
        _fail(i)
    # Parse first key.
    key, ni = _decode_string(s, i)
    i = ni
    i = _skip_ws(s, i)
    if i >= n or s[i] != ":":
        _fail(i)
    i += 1
    i = _skip_ws(s, i)
    if i >= n:
        _fail(i)
    if s[i] == "{":
        return _parse_object_top(s, i)
    if s[i] == "[":
        return _parse_array_top(s, i)
    if s[i] in "tn":
        if s.startswith("true", i):
            i += 4
        elif s.startswith("false", i):
            i += 5
        elif s.startswith("null", i):
            i += 4
        else:
            _fail(i)
        return {}
    if s[i] == "-" or s[i].isdigit():
        val = _parse_number(s, i)
        if isinstance(val, _ReturnSignal):
            i = val.pos
            j = _skip_ws(s, i)
            if j != n:
                _fail(j)
            return val.value
        if isinstance(val, _TopReturn):
            i = val.pos
            j = _skip_ws(s, i)
            if j != n:
                _fail(j)
            return val.value
        return {}

    # For an empty top-level object with no entries ({}), handled above.
    # If more text remains, invalid.
    _fail(i)


def _parse_array_top(s: str, i: int) -> list:
    n = len(s)
    if i >= n or s[i] != "[":
        _fail(i)
    i += 1
    i = _skip_ws(s, i)
    if i >= n:
        _fail(i)
    if s[i] == "]":
        return []
    if s[i] == "{":
        return _parse_object_top(s, i)
    if s[i] == "[":
        return _parse_array_top(s, i)
    if s[i] in "tn":
        if s.startswith("true", i):
            i += 4
        elif s.startswith("false", i):
            i += 5
        elif s.startswith("null", i):
            i += 4
        else:
            _fail(i)
        return []
    if s[i] == "-" or s[i].isdigit():
        val = _parse_number(s, i)
        if isinstance(val, _ReturnSignal):
            i = val.pos
            j = _skip_ws(s, i)
            if j != n:
                _fail(j)
            return val.value
        if isinstance(val, _TopReturn):
            i = val.pos
            j = _skip_ws(s, i)
            if j != n:
                _fail(j)
            return val.value
        return []
    _fail(i)
